/** Arabic operating reference. Links open selection screens, never invented record IDs. */
export interface GuideLink { readonly label: string; readonly path: string }
export interface GuideTopic {
  readonly id: string;
  readonly title: string;
  readonly summary: string;
  readonly before: string;
  readonly steps: readonly string[];
  readonly fields: readonly (readonly [string, string])[];
  readonly result: string;
  readonly questions: readonly (readonly [string, string])[];
  readonly links: readonly GuideLink[];
  readonly limitation?: string;
}
export interface GuideSection { readonly id: string; readonly title: string; readonly description: string; readonly topics: readonly GuideTopic[] }
const links = (...items: readonly (readonly [string, string])[]): GuideLink[] => items.map(([label, path]) => ({ label, path }));
const topic = (id: string, title: string, summary: string, before: string, steps: readonly string[], fields: GuideTopic['fields'], result: string, questions: GuideTopic['questions'], related: GuideLink[], limitation?: string): GuideTopic => ({ id, title, summary, before, steps, fields, result, questions, links: related, ...(limitation === undefined ? {} : { limitation }) });

const BASE_GUIDE_SECTIONS: readonly GuideSection[] = [
  ACCOUNT_GUIDES,
  { id: 'featured-identity', title: 'إعلانات الرئيسية وظهور المكاتب', description: 'النشر واشتراك الهوية وحماية العميل.', topics: [featuredIdentityGuide] },
  { id: 'account-followup', title: 'متابعة الحساب والمعاينات والإعلانات', description: 'إشعارات حالات الحساب والمعاينات والطلبات والإعلانات داخل المنصة فقط. البريد الإلكتروني مخصص لرموز التحقق OTP.', topics: [
    topic('account-communication', 'إشعار العميل وإرسال عقار وإدارة الدخول', 'التواصل من تفاصيل المستخدم بدل الاكتفاء بعرض بياناته.', 'صلاحية إدارة الحسابات؛ حساب العرض فقط لا يستطيع تنفيذ الإجراءات.', [], [['إشعار داخل الموقع', 'لا يحتاج خدمة بريد؛ يصل إلى إشعارات صاحب الحساب.'], ['إرسال عقار', 'الرمز لعقار منشور، والرابط يُنشأ تلقائيًا.'], ['تعطيل الحساب', 'يحافظ على طلبات العميل وسجل المعاملات؛ لا يحذف بياناته نهائيًا.']], 'إجراء محفوظ في سجل الإدارة وإشعار موجه للحساب الصحيح.', [['هل الإشعار يظهر أثناء انتظار اعتماد العارض؟', 'نعم؛ يستطيع الدخول وقراءة إشعارات الإدارة وإكمال النواقص، مع بقاء أدوات التشغيل محجوبة حتى التفعيل.']], links(['المستخدمون', '/admin/users'], ['مقدمو العقارات', '/admin/providers'], ['إشعارات العارض', '/provider/notifications'], ['إشعارات الباحث', '/seeker/notifications'])),
    topic("viewing-administration", "طلبات المعاينة: تنظيم زيارة العميل للعقار", "راجع الموعد وأكّده أو غيّره، ثم سجّل نتيجة الزيارة.", "صلاحية عرض المعاينات وصلاحية إدارة الطلبات.", ["افتح طلبات المعاينة، واختر الحالة ثم «التفاصيل والإجراء» بجوار العقار.", "الموعد والرقم اختياريان. الطلب بلا موعد يحتاج تحديده قبل التأكيد. راجع الرقم واختيار مكالمة أو واتساب.", "اختَر «تأكيد الموعد» بعد الاتفاق، أو «تغيير الموعد» وحدد تاريخًا وساعة جديدين في المستقبل.", "اكتب رسالة واضحة من 5 إلى 500 حرف. تظهر للعميل ومقدّم العقار في إشعار داخل المنصة وتُحفظ في سجل الإدارة؛ ليست ملاحظة سرية.", "لإلغاء الزيارة اختَر «إلغاء المعاينة» ووضّح السبب. بعد الزيارة الفعلية اختَر «تمت المعاينة».", "اضغط زر الإجراء وانتظر تأكيد الحفظ. المعاينة الملغاة أو المكتملة ليس عليها إجراءات أخرى. عند التعارض حدّث القائمة وراجع الحالة قبل إعادة المحاولة."], [["بانتظار التأكيد", "العميل اقترح الموعد ولم يتم تأكيده بعد."], ["موعد جديد ينتظر التأكيد", "تم تغيير الموعد ويحتاج تأكيد الاتفاق."], ["رسالة للعميل وسبب الإجراء", "تظهر للعميل ومقدّم العقار؛ اكتب نصًا مناسبًا لهما."]], "موعد واضح وحالة محفوظة، مع إشعار للأطراف المرتبطة بالمعاينة.", [["ليه الصفحة دي موجودة؟", "لتنظيم زيارة فعلية للعقار ومتابعة هل تأكدت أو اتغيّرت أو تمت؛ طلب التواصل العام له صفحة مستقلة."], ["هل الحفظ يبعث واتساب؟", "الإجراء يرسل إشعارًا داخل المنصة؛ لا يرسل رسالة واتساب تلقائيًا."]], [{"label": "طلبات المعاينة", "path": "/admin/viewing-requests"}, {"label": "معاينات الباحث", "path": "/seeker/viewings"}]),
    topic('simple-advertising-contact', 'إعلان مدفوع أو مجاني وبيانات التواصل', 'طلب إعلان مختصر وتفعيل بقرار واضح، مع إعدادات تواصل موحدة.', 'العارض المعتمد يطلب الإعلان؛ الإدارة تحدد الموضع والسعر والفترة.', ['من الإعلانات أدخل رقم التواصل والغرض من الإعلان فقط؛ لا تحتاج كودًا أو مفتاح شراء.', 'الإدارة تراجع الطلب وتحدد موضع العرض وفترته وسعره. العارض يقبل عرض السعر ثم يرفع إثبات الدفع إذا كان الإعلان مدفوعًا.', 'في الجدولة، عدّل الفترة المنتهية إلى فترة صالحة. راجع مدة العرض بتوقيت مصر.', 'للإعلان المجاني اختر اعتماد مجاني بدون دفع واكتب سبب الإعفاء؛ لا تُنشأ دفعة أو إيصال وهمي.', 'من إعدادات الإدارة > معلومات التواصل اضبط التليفون وواتساب والخريطة وفيسبوك وإنستجرام، ثم احفظ بسبب واضح. استبدل أمثلة التواصل ببيانات المنصة الفعلية.'], [['موضع الإعلان', 'تختاره الإدارة من أسماء مواضع معتمدة؛ ليس مفتاحًا يشتريه العارض.'], ['مدة العرض', 'الفارق الفعلي بين البداية والنهاية، مع التوقيت الصيفي والشتوي.'], ['بيانات تجريبية', 'أمثلة لحين ضبط بيانات حقيقية؛ زر التعبئة التجريبية لا يحفظ قبل الضغط على حفظ.']], 'طلب بسيط وقرار تشغيل محفوظ وروابط تواصل موحدة في الفوتر.', [['هل المجاني يلغي صلاحيات الإدارة؟', 'لا؛ يحتاج صلاحية جدولة الإعلانات وسببًا موثقًا.'], ['هل أقدر أترك السعر في البحث فارغًا؟', 'نعم؛ الحد الأدنى والأقصى اختياريان ويمكن استخدام حد واحد فقط.']], links(['طلب إعلان', '/provider/ads'], ['إدارة الإعلانات', '/admin/ads/requests'], ['إعدادات التواصل', '/admin/settings/contact'], ['بحث العقارات', '/properties']))
  ] },
  { id: 'start', title: 'ابدأ هنا: الحساب والتنقل والحفظ', description: 'طريقة استخدام الدليل والتنقل والحفظ، ومعنى الحالات والصلاحيات.', topics: [
    topic('use-guide', 'استخدام الدليل التفاعلي', 'مرجع لحسابك مع بحث وفهرس وروابط للصفحات.', 'الدخول بحسابك؛ قراءة الدليل لا تمنح صلاحيات تشغيلية جديدة.', ['دليل الاستخدام يظهر بأيقونة كتاب في القائمة الجانبية لكل حساب. اضغط أيقونة الحساب أعلى اللوحة لفتح قائمة الإعدادات والدليل وتسجيل الخروج؛ إعدادات الإدارة تخص المنصة وتخضع لصلاحياتك. أغلق القائمة بالضغط خارجها أو Escape.', 'اختر قسمًا من الفهرس أو ابحث باسم الصفحة أو السؤال؛ البحث يشمل الشرح والحقول والأسئلة.', 'اضغط عنوان الموضوع لفتح الشرح أو طيه. «فتح الكل» و«طي الكل» يخصّان النتائج المعروضة.', 'استخدم «تكبير» للقراءة في مساحة مستقلة، وEscape للعودة. «تصغير» يخفي مساحة القراءة مع إبقاء أدوات التحكم.', 'زر الرابط بجانب الموضوع يفتح صفحة المهمة في تبويب جديد حتى لا تفقد موضع القراءة. انسخ رابط الموضوع لمشاركته مع مسؤول آخر.', 'الطباعة تشمل الموضوعات الظاهرة حسب البحث والقسم الحالي؛ امسح البحث واختر «كل الأقسام» لطباعة الدليل كاملًا.'], [['حفظ موضع القراءة', 'تُحفظ الأقسام المفتوحة وآخر موضوع في هذا المتصفح فقط؛ لا تُرسل هذه التفضيلات للآخرين.'], ['لغة الشرح', 'المحتوى التفصيلي عربي. لغة أدوات الدليل وروابط الصفحات تتبع لغة الواجهة.']], 'تصل إلى الخطوات المناسبة مع الاحتفاظ بموضعك عند الرجوع.', [['هل الرابط يفتح حساب العميل؟', 'لا. صفحات السيكر والمقدّم تحتاج حسابًا بالدور المناسب؛ استخدم جلسة منفصلة عند اختبارها.'], ['هل البحث يبحث في العملاء؟', 'لا؛ يبحث في نص هذا الدليل فقط.']], links(['نظرة عامة', '/admin'], ['دليل الاستخدام', '/admin/user-guide'])),
    topic('dashboard', 'لوحة الإدارة والبحث والقوائم', 'متابعة مؤشرات المنصة والوصول إلى الصفحات.', 'حساب إدارة نشط؛ بعض الصفحات تحتاج صلاحيات إضافية.', [], [['الفلتر', 'اختيار الحالة أو النوع يضيّق النتائج؛ مسح الفلتر يعيد القائمة.'], ['الوقت', 'راجع المنطقة الزمنية الظاهرة في المواعيد، خاصة عند التنسيق مع عميل.']], 'ترى السجلات المطابقة فقط وتفتح تفاصيل السجل الصحيح.', [['لماذا لا توجد نتائج؟', 'امسح البحث والفلاتر وتحقق من الصفحة التالية ومن صلاحية الحساب؛ القائمة الفارغة لا تعني عطلًا بالضرورة.'], ['لماذا الزر غير متاح؟', 'قد يكون دورك للعرض فقط أو حالة السجل لا تسمح بهذا الإجراء.']], links(['لوحة الإدارة', '/admin'], ['الموقع العام', '/'])),
    topic('save-language', 'الحفظ وتغيير اللغة والتعارض', 'تجنب فقدان تعديلاتك وفهم رسائل الحفظ.', 'راجع السجل واللغة قبل إدخال محتوى.', ['اكتب المحتوى العربي في حقل العربية والإنجليزي في حقل English؛ تبديل لغة الواجهة لا يترجم المحتوى.', 'اكتب سبب تغيير واضحًا عند طلبه، مثل «تصحيح رقم التواصل».', 'اضغط الحفظ مرة واحدة وانتظر رسالة النجاح؛ وجود البيانات في الحقول لا يعني أنها حُفظت.', 'احفظ قبل الانتقال لصفحة أخرى أو إعادة التحميل؛ احتفاظ بعض النماذج بالمدخلات أثناء تغيير اللغة ليس حفظًا دائمًا.', 'عند تعارض الإصدار، احتفظ بنص تعديلاتك، أعد تحميل أحدث سجل، ثم راجع الفرق قبل الحفظ.'], [['سبب التغيير', 'شرح إداري لما تغيّر ولماذا؛ لا تضع كلمات مرور أو بيانات لا تحتاجها المراجعة.'], ['الإصدار', 'رقم يمنع استبدال تعديل مسؤول آخر ببيانات قديمة.']], 'تُحفظ البيانات ويظهر التأكيد؛ التغيير قابل للتتبع في سجل التدقيق.', [['هل errors.conflict يعني النسبة خطأ؟', 'ليس دائمًا. قد تكون هناك مسودة موجودة أو تعديل متزامن؛ راجع موضوع تعارض العمولات.'], ['ظهرت errors.notFound؟', 'السجل غير موجود أو غير متاح؛ ارجع للقائمة وافتح السجل منها، ثم راجع الصلاحيات.']], links(['سجل التدقيق', '/admin/audit-logs'], ['فريق العمل', '/admin/content/team']))
  ] },
  { id: 'accounts', title: 'الحسابات والتوثيق والبلاغات', description: 'الباحثون ومقدمو العقارات ومراجعة المستندات وقيود الحسابات.', topics: [
    topic('users', 'المستخدمون والباحثون ومقدمو العقارات', 'اختيار الحساب الصحيح ومراجعة حالته.', 'صلاحية قراءة الحسابات؛ التعديل يحتاج صلاحية الإجراء.', ['افتح جميع المستخدمين، أو قائمة الباحثين، أو مقدمي العقارات حسب نوع الحساب.', 'طبّق البحث والفلاتر المتاحة، ثم افتح «عرض» للسجل المطلوب.', 'راجع الاسم والبريد والحالة ونوع الحساب قبل إجراء أي تغيير.', 'اختر الإجراء المتاح في تفاصيل الحساب واكتب السبب المطلوب ثم انتظر التأكيد.'], [['معرّف الحساب', 'مرجع فريد للحساب، مختلف عن رقم الهاتف ومعرّف المؤسسة.'], ['نوع المقدّم', 'فرد أو مكتب وساطة أو شركة تطوير؛ لكل نوع بيانات ومستندات وقدرات مختلفة.']], 'تراجع أو تغيّر الحساب المقصود دون الخلط بينه وبين المؤسسة أو عضو فريق الموقع.', [['هل حذف عضو من فريق العمل يحذف مستخدمًا؟', 'لا؛ أعضاء صفحة الفريق محتوى للموقع، وليسوا حسابات دخول.'], ['المكتب لا يرى مشروعات؟', 'المشروعات مرتبطة بشركات التطوير؛ استخدم العقارات للمكتب.']], links(['كل المستخدمين', '/admin/users'], ['الباحثون', '/admin/property-seekers'], ['مقدمو العقارات', '/admin/providers'])),
    topic('verification', 'مراجعة وتفعيل مقدم العقار', 'الموافقة أو طلب معلومات أو رفض طلب التسجيل بعد مراجعة المستندات.', 'صلاحية مراجعة التوثيق؛ المستندات خاصة ولا تُعرض للزوار.', ['افتح قائمة التوثيق وحدد الطلب.', 'راجع نوع المقدّم والبيانات القانونية والتجارية والمستندات المرفوعة وحالة فحصها.', 'إذا كانت بيانات مطلوبة ناقصة، اختر طلب معلومات وحدد النواقص بوضوح بدل الموافقة على طلب غير مكتمل.', 'إذا كان الطلب صالحًا، استخدم إجراء الاعتماد المتاح واكتب السبب. الرفض يحتاج سببًا مفهومًا لصاحب الطلب.', 'تحقق من حالة الطلب بعد الحفظ؛ يصل سبب القرار في إشعارات الحساب. أثناء المراجعة وطلب المعلومات يحتفظ العارض بالدخول، ويمكن للإدارة قبوله أو رفضه بعد طلب المعلومات.'], [['المستند', 'رفع الملف وحده لا يغني عن إكمال الحقول المطلوبة؛ يجب أن يكون قابلًا للقراءة ومقبولًا بعد الفحص.'], ['صلاحية صاحب الحساب', 'تحديد ما إذا كانت لصاحب الحساب صلاحية مسجلة لتمثيل المكتب أو الشركة؛ هذه إجابة في البيانات وليست ملفًا.']], 'تتغير حالة الطلب حسب القرار، وتُتاح لوحة المقدّم الكاملة بعد الاعتماد المناسب.', [['لماذا يظهر «طلبك قيد المراجعة»؟', 'حالة الطلب لم تعتمد بعد؛ هذه ليست مشكلة تسجيل دخول.'], ['لماذا «لا يمكن الانتقال للمراجعة» رغم رفع الأوراق؟', 'راجع قائمة النواقص: عنوان أو بيانات مؤسسة أو صلاحية ممثل قد تكون ناقصة. افتح التسجيل بحساب المقدّم وأكمل الحقول مع الحفاظ على الملفات المرفوعة.']], links(['قائمة التوثيق', '/admin/verification'], ['حسابات المقدّمين', '/admin/providers'])),
    topic('account-reports', 'بلاغات الحسابات وقيودها', 'فحص البلاغ قبل اتخاذ إجراء على الحساب.', 'صلاحية قراءة البلاغات، وصلاحية مناسبة لإجراء التقييد.', ['افتح بلاغات الحسابات ثم تفاصيل البلاغ من القائمة.', 'راجع الحساب المبلّغ عنه والسبب والأدلة المتاحة؛ البلاغ ليس إثباتًا تلقائيًا للمخالفة.', 'سجّل قرار البلاغ والإجراء المتاح مع سبب واضح.', 'راجع صفحة قيود الحسابات لمعرفة القيود المسجلة؛ لا تستبدل قرار البلاغ بتغيير غير مرتبط به.'], [['البلاغ', 'شكوى تحتاج مراجعة.'], ['القيد', 'إجراء على الحساب؛ راجع أثره وحالته قبل التنفيذ.']], 'يُسجَّل قرار المراجعة دون تجاهل البلاغ أو تقييد حساب خاطئ.', [['لا أستطيع تنفيذ إجراء؟', 'راجع صلاحيات دورك وحالة البلاغ؛ القراءة وحدها لا تمنح حق التقييد.']], links(['بلاغات الحسابات', '/admin/account-reports'], ['قيود الحسابات', '/admin/account-restrictions']))
  ] },
  { id: 'properties', title: 'العقارات والمشروعات والبيانات المرجعية', description: 'المراجعة والنشر والبلاغات والتصنيفات والأحياء والمميزات.', topics: [
    topic('property-review', 'مراجعة العقارات ونشرها', 'فحص العقار قبل ظهوره للزوار.', 'صلاحية إدارة العقارات أو مراجعتها حسب الإجراء.', [], [['السعر', 'المبلغ ونوع المعاملة وخطة السداد؛ سعر البيع يختلف عن قيمة الإيجار ودوريته.'], ['حالة النشر', 'وجود العقار في الإدارة لا يعني ظهوره للعامة.']], 'يعرف المقدّم القرار ويظهر العقار للعامة فقط عند استيفاء شروط النشر.', [['العقار غير ظاهر بعد الحفظ؟', 'راجع حالة النشر والاعتماد والنشاط والانتهاء؛ الحفظ ليس نشرًا تلقائيًا في كل مسار.']], links(['كل العقارات', '/admin/properties'], ['مراجعة العقارات', '/admin/properties/review'], ['العقارات العامة', '/properties'])),
    topic('duplicates-reports', 'العقارات المكررة وبلاغات العقارات', 'التمييز بين التشابه والتكرار الحقيقي ومراجعة الشكاوى.', 'صلاحية قراءة السجلات والبلاغات والإجراء المطلوب.', ['افتح العقارات المكررة المحتملة وقارن الموقع والبيانات والصور والسجلات المتشابهة.', 'لا تعتبر اقتراح التشابه قرار حذف؛ راجع تفاصيل كل عقار ومقدّمه.', 'افتح بلاغات العقارات وفحص السبب والسجل المشار إليه.', 'نفذ الإجراء المتاح بعد التأكد واكتب السبب؛ احتفظ بمرجع البلاغ عند متابعة المشكلة.'], [['تكرار محتمل', 'تنبيه للمراجعة وليس تأكيدًا أن العقارين سجل واحد.'], ['بلاغ عقار', 'يرتبط بعقار معين؛ يختلف عن بلاغ حساب أو منشور.']], 'تُعالج السجلات والشكاوى بناءً على مراجعة واضحة.', [['هل أصحح العقار من البلاغ؟', 'استخدم الإجراء المتاح أو ارجع لإدارة العقارات؛ إغلاق البلاغ وحده لا يغيّر بيانات العقار.']], links(['التكرار المحتمل', '/admin/properties/possible-duplicates'], ['بلاغات العقارات', '/admin/property-reports'])),
    topic('projects', 'مشروعات المطورين ووحداتها', 'مراجعة المشروع وربط الوحدات بالمطور الصحيح.', 'حساب مطور لإنشاء مشروعات؛ الإدارة تحتاج صلاحية إدارة أو مراجعة المشروعات.', [], [['المشروع', 'مجموعة تابعة لمطور، وليس نوعًا بديلًا لحساب مكتب وساطة.'], ['الوحدة', 'عقار مرتبط بمشروع عند اختيار الرابط الصحيح في بياناته.']], 'تظهر المشروعات والوحدات المنشورة للمطور الصحيح.', [['المكتب يرى صفحة دخول عند فتح المشروعات؟', 'حساب المكتب لا يتحول لمطور بالموافقة عليه؛ المشروعات للمطورين. استخدم قائمة عقارات المكتب.']], links(['المشروعات', '/admin/projects'], ['مراجعة المشروعات', '/admin/projects/review'], ['المطورون', '/developers'])),
    topic('categories', 'تصنيفات وأنواع العقارات', 'إدارة أسماء الفئات وترتيبها ونشاطها.', 'صلاحية إدارة البيانات المرجعية.', [], [['الترتيب', 'يحدد موقع العنصر في القوائم، وليس عدد العقارات.'], ['عدد العقارات', 'يعتمد على العقارات المنشورة والمتاحة فعليًا؛ لا تدخل أرقامًا تسويقية بدل العدد.']], 'تظهر الفئة باسم وترتيب صحيحين دون أرقام وهمية.', [['العدد صفر؟', 'قد لا توجد عقارات متاحة في هذه الفئة؛ إضافة اسم فئة لا يضيف عقارات.']], links(['التصنيفات', '/admin/property-categories'], ['الرئيسية', '/'])),
    topic('locations-features', 'الأحياء والمناطق والمميزات والخدمات', 'تجهيز القوائم التي يختار منها المقدّم والباحث.', 'صلاحية إدارة البيانات المرجعية.', [], [['المنطقة', 'اختيار مكان حقيقي؛ لا تستخدمها لإدخال عنوان كامل في اسم الحي.'], ['الميزة', 'خدمة أو خاصية يمكن اختيارها للعقار؛ ليست وصفًا طويلًا للعقار.']], 'تصبح خيارات البحث والإدخال متسقة.', [['الخيار الجديد لا يظهر؟', 'راجع النشاط وعلاقة المنطقة وحفظ السجل، ثم أعد تحميل النموذج.']], links(['المناطق', '/admin/locations'], ['المميزات', '/admin/features']))
  ] },
  { id: 'requests', title: 'الطلبات والمعاينات والمتابعة', description: 'أنواع الطلبات والتأخير والتعيين والملاحظات وحل المشكلات.', topics: [
    topic('requests-list', 'أنواع الطلبات وفتح التفاصيل', 'اختيار قائمة الطلبات المناسبة والوصول إلى بياناتها.', 'صلاحية قراءة الطلبات.', ['استخدم «كل الطلبات» للرؤية العامة، أو افتح قائمة نوع محدد.', 'طلبات التواصل تخص الاستفسار عن عقار؛ المعاينات تخص المواعيد؛ البحث يصف احتياج الباحث؛ طلبات العملاء ينشئها مقدم الخدمة.', 'حدد الحالة والنوع والبحث ثم طبّق الفلتر.', 'اضغط «عرض» على الصف الصحيح؛ يفتح تفاصيل الطلب، وليس صفحة العقارات العامة.', 'راجع اسم العميل ورقم الهاتف والعقار والمقدّم والموعد والحالة؛ بعض البيانات لا تظهر إلا لمن يملك صلاحية الوصول.', 'اضغط «فتح العقار» لعرض العقار المنشور في تبويب آخر، أو «فتح العقار في الإدارة» لمراجعة السجل حسب صلاحيتك؛ العقار غير المنشور له رابط الإدارة فقط.', 'البحث يقبل كود العقار مثل SDT-1234 أو معرّف العقار أو الطلب الكامل المكوّن من 24 خانة أو اسم العميل أو هاتفه. امسح الفلاتر إذا لم تظهر نتيجة؛ المعرّف الناقص أو الزائد لا يحدد سجلًا.'], [['معرّف الطلب', 'مرجع المتابعة؛ ليس رقم العميل.'], ['المصدر', 'يوضح قناة أو نوع إنشاء الطلب.']], 'ترى الطلب الصحيح وبياناته المتاحة للمتابعة.', [['رابط الطلب لا يفتح؟', 'ارجع لقائمة الطلبات وابحث عن السجل؛ قد تكون صلاحية القراءة ناقصة أو السجل غير متاح.']], links(['كل الطلبات', '/admin/requests'], ['طلبات العملاء', '/admin/customer-requests'], ['التواصل', '/admin/contact-requests'], ['المعاينات', '/admin/viewing-requests'], ['البحث', '/admin/search-requests'])),
    topic('overdue', 'الطلبات المتأخرة', 'تحديد الطلبات التي تجاوزت موعد المتابعة.', 'صلاحية قراءة الطلبات؛ إدارة الحالة تحتاج صلاحية إضافية.', ['افتح الطلبات المتأخرة وراجع موعد المتابعة ومدة التأخير والمسؤول.', 'اضغط عرض، وتحقق من آخر حالة وملاحظات قبل التواصل مع العميل.', 'سجّل التواصل أو الانتقال المناسب من الإجراءات المتاحة، مع السبب.', 'لا تعتبر عرض الطلب أو فتحه معالجة للتأخير؛ راجع الموعد والحالة بعد حفظ الإجراء.'], [['مدة التأخير', 'مقدار تجاوز الموعد المحسوب؛ ليس تاريخ إنشاء الطلب.'], ['المسؤول', 'الشخص المعيّن للمتابعة، وقد يظهر غير مسند.']], 'تكون المتابعة مسجلة بدل الاكتفاء بقراءة القائمة.', [['هل يجب تغيير الحالة لإزالة الطلب من القائمة؟', 'غيرها فقط لتعكس ما حدث فعلًا؛ راجع موعد المتابعة وقواعد الطلب، ولا تغلقه لمجرد إخفاء التأخير.']], links(['المتأخرة', '/admin/overdue-requests'], ['كل الطلبات', '/admin/requests'])),
    topic('request-actions', 'حالات الطلب والتعيين والملاحظات', 'متابعة العمل داخل تفاصيل الطلب.', 'صلاحيات تغيير الحالة أو تعيين الطلب أو إضافة ملاحظة حسب المهمة.', [], [['معرّف المسؤول', 'مرجع حساب الإدارة المكوّن من 24 خانة؛ ليس الاسم أو البريد أو الهاتف. راجعه من بيانات مستخدم الإدارة.'], ['حالات الطلب', 'جديد، قيد المراجعة، تم التواصل، مجدول، يحتاج معلومات، قيد التنفيذ، تم الحل، ملغى، مغلق؛ يظهر المسموح فقط.']], 'يتوثق العمل والمسؤول دون تجاوز انتقال غير مسموح.', [['لا تظهر إجراءات؟', 'تغيير الحالة يتطلب صلاحية إدارة الطلبات، والقراءة تتطلب صلاحية عرض الطلبات. تعيين المسؤول وإضافة الملاحظات لهما صلاحيتان منفصلتان. راجع الأدوار والصلاحيات بدل افتراض أن كل حساب إدارة يستطيع كل إجراء.']], links(['الطلبات', '/admin/requests'], ['طلبات التواصل', '/admin/contact-requests'], ['مستخدمو الإدارة', '/admin/admin-users'], ['الأدوار والصلاحيات', '/admin/roles'], ['إشعارات الباحث', '/seeker/notifications'], ['طلبات الباحث', '/seeker/requests'])),
    topic('request-issues', 'بلاغات ومشكلات الطلبات', 'حل شكوى مرتبطة بطلب أو إغلاقها بسبب موثق.', 'صلاحية معالجة بلاغات الطلبات.', ['افتح البلاغ واستخدم تفاصيل الطلب المرتبط لفهم المشكلة.', 'راجع الفئة: تكرار أو إساءة أو بيانات خاطئة أو خدمة أو أخرى.', 'اختر حل البلاغ عند معالجة السبب، أو إغلاقه عندما لا يلزم إجراء، مع تفسير القرار.', 'احفظ وتحقق من حالة البلاغ؛ تعديل البلاغ لا يغيّر كل بيانات الطلب تلقائيًا.'], [['سبب الإجراء', 'ما تم فحصه وما القرار، وليس مجرد «تم».']], 'تُحفظ نتيجة مراجعة البلاغ ويرتبط القرار بالسجل الصحيح.', [['البلاغ والطلب لهما حالتان مختلفتان؟', 'نعم؛ حل البلاغ يخص الشكوى، وإغلاق الطلب يخص عملية خدمة العميل.']], links(['مشكلات الطلبات', '/admin/request-issues'], ['كل الطلبات', '/admin/requests']))
  ] },
  { id: 'content', title: 'المقالات والمجتمع ومحتوى الموقع', description: 'المراجعة والبلاغات وإدارة الفريق والنبذة والعداد والنصائح والرئيسية.', topics: [
    topic('articles', 'إنشاء المقالات ومراجعتها', 'تجهيز المحتوى ونشره في المقالات العامة.', 'صلاحيات قراءة أو إدارة أو نشر المقالات وفق دورك.', [], [], 'يُحفظ المحتوى وتعرف هل هو مسودة أم منشور.', [], links(['المقالات', '/admin/articles'], ['المقالات العامة', '/articles'])),
    topic("article-categories", "تصنيفات المقالات", "اسم يجمع المقالات المتشابهة؛ وصف التصنيف اختياري.", "صلاحية إدارة تصنيفات المقالات.", ["افتح تصنيفات المقالات واضغط «إضافة تصنيف»، أو عدّل تصنيفًا موجودًا.", "اكتب اسمًا مثل «نصائح شراء» أو «نصائح إيجار» بالعربية أو الإنجليزية. لا تحتاج كتابة مقال هنا.", "لو محتاج توضيحًا افتح «إضافة وصف مختصر (اختياري)» واكتب سطرًا. يمكن تركه فارغًا؛ ولحذف الوصف القديم امسح حقوله واحفظ.", "حدّد ترتيب الظهور: الرقم الأصغر أولًا. حدّد هل التصنيف نشط.", "اكتب سبب التغيير واحفظ. عند إنشاء مقال اختَر هذا التصنيف من قائمة التصنيفات."], [["اسم التصنيف", "اسم المجموعة التي ينتمي إليها المقال."], ["الوصف المختصر", "سطر اختياري للتوضيح؛ ليس محتوى مقال."], ["الترتيب", "الرقم الأصغر يظهر أولًا."]], "تصنيف بسيط يمكن اختياره عند إنشاء المقال.", [["ليه أكتب محتوى للتصنيف؟", "مش مطلوب. يكفي الاسم، والوصف اختياري. محتوى المقال يُكتب في صفحة المقالات."]], [{"label": "تصنيفات المقالات", "path": "/admin/article-categories"}, {"label": "المقالات", "path": "/admin/articles"}]),
    topic('community', 'مراجعة المجتمع والبلاغات وإلغاء التعليقات', 'مراجعة المنشورات ومعالجة المحتوى المخالف.', 'صلاحية مراجعة المجتمع؛ تعليقات الجمهور غير متاحة في النسخة الحالية.', [], [['مراجعة المنشور', 'تخص المنشور قبل ظهوره للعامة.'], ['البلاغ', 'شكوى على محتوى منشور تستدعي فحصًا منفصلًا.']], 'يُعرض المحتوى المقبول وتُراجع المخالفات مع بقاء التعليقات العامة معطلة.', [['لماذا لا يوجد زر تعليق؟', 'إلغاء التعليقات العامة قرار لحماية المجتمع؛ لا توجد دورة مراجعة تعليقات جديدة.'], ['هل الإبلاغ يحذف المنشور فورًا؟', 'لا تعتبر الإبلاغ قرار حذف؛ الإدارة تراجع البلاغ والإجراء المتاح.']], links(['المجتمع الإداري', '/admin/community'], ['بلاغات المجتمع', '/admin/community/moderation'], ['أرشيف التعليقات', '/admin/community/comments'], ['المجتمع العام', '/community'])),
    topic('about', 'النبذة عن المنصة', 'تعديل المقدمة والفقرات التعريفية المنشورة.', 'صلاحية إدارة المحتوى؛ النشر يحتاج صلاحية نشر المحتوى.', [], [['العنوان والنص', 'تُعدل بيانات الفقرة المختارة وحدها؛ كل لغة لها حقول مستقلة.'], ['معاينة', 'تقرأ النص داخل لوحة الإدارة؛ لا تنشر ولا تحفظ تعديلات.']], 'يُحفظ تعديل الفقرة المختارة ويظهر محتواها العام إذا كانت منشورة ونشطة.', [['الكتابة لا تظهر للعامة؟', 'راجع رسالة نجاح الحفظ، وحالة منشور، وخيار نشط، ثم أعد فتح الصفحة العامة.'], ['ظهر خطأ حفظ؟', 'التعديل المكتوب يبقى في النموذج؛ صحّح السبب المذكور ثم أعد الحفظ.']], links(['إدارة النبذة', '/admin/content/about'], ['من نحن', '/about'])),
    topic('team', 'فريق العمل: إضافة وتعديل وحذف وإخفاء', 'إدارة الأشخاص الظاهرين في صفحة فريق الموقع.', 'صلاحية إدارة المحتوى؛ عضو الفريق ليس حساب مستخدم.', [], [], 'تتحدث صفحة الفريق أو يُحذف سجل المحتوى بعد التأكيد.', [], links(['إدارة الفريق', '/admin/content/team'], ['الفريق العام', '/team'])),
    topic('population', 'عداد سكان مدينة السادات', 'حفظ رقم موثق ونشره على الرئيسية أو إخفاؤه.', 'صلاحية إدارة المحتوى، وصلاحية نشر المحتوى لاختيار «متاح». استخدم بيانًا له مصدر.', ['هذه الصفحة تعدّل عدادًا واحدًا للمدينة؛ لا تحتاج إضافة سجل جديد لكل تعديل.', 'اختر «متاح» لنشر العدد، ثم أدخل عددًا صحيحًا في «القيمة» من صفر إلى 100 مليون.', 'أدخل اسم الجهة التي أصدرت البيان بالعربية أو الإنجليزية. اسم المصدر ليس العدد نفسه.', 'أدخل رابط المصدر كاملًا وتاريخ البيان باليوم والشهر والسنة؛ الحقل تاريخ فقط ولا يحتاج وقتًا. رابط محادثة أو صورة شخصية لا يوثق رقم السكان؛ استخدم رابط البيان الذي أخذت منه الرقم.', 'اكتب سبب التغيير من 5 إلى 500 حرف، ثم احفظ وانتظر «تم حفظ عداد السكان بنجاح». ظهور رسالة نقص أو خطأ يعني أن التعديل لم يُحفظ؛ البيانات المكتوبة تبقى لتصحيحها.', 'راجع الرئيسية بعد الحفظ. رقم صفحة عداد السكان هو المعتمد عند وجود سجل؛ إعدادات العرض تتحكم في إظهار العداد ويمكن أن تغيّر عنوانه، ولا تستبدل العدد الموثق برقم قديم.', 'اختر «مسودة» أو «غير متاح» واحفظ لإخفاء الرقم؛ لا يظهر رقم قديم بدلًا منه.'], [['القيمة', 'عدد السكان المستند إلى البيان؛ مطلوب عند الحالة «متاح».'], ['اسم المصدر', 'اسم الجهة التي أصدرت الرقم بالعربية أو الإنجليزية؛ مطلوب عند النشر.'], ['رابط المصدر', 'رابط كامل للبيان؛ مطلوب عند النشر.'], ['تاريخ البيان', 'تاريخ البيانات الإحصائية؛ مطلوب عند النشر وليس تاريخ الإدخال بالضرورة.']], 'يُحفظ آخر تعديل، ويظهر العدد الموثق على الرئيسية إذا كانت الحالة متاحًا والظهور مفعّلًا.', [['لم يُحفظ العدد؟', 'راجع الرسالة والحقول المحددة: قيمة صحيحة واسم مصدر ورابط وتاريخ وسبب تغيير. ترك تاريخ البيان فارغًا يمنع نشر الرقم.'], ['حفظته ولا يظهر؟', 'اختر متاحًا، وتأكد من تفعيل إظهار عداد السكان في إعدادات العرض ثم أعد فتح الرئيسية.'], ['ظهر تعارض؟', 'احتفظ بما كتبته، وأعد فتح الصفحة لجلب أحدث سجل قبل حفظ تعديل جديد؛ قد يكون مسؤول آخر عدّل العداد.']], links(['إدارة العداد', '/admin/content/population-counter'], ['إعدادات العرض', '/admin/settings/display'], ['الرئيسية', '/'])),
    topic("tips-home", "النصائح وأقسام الصفحة الرئيسية", "إدارة النصوص والترتيب والنشاط في الرئيسية.", "صلاحية إدارة محتوى الرئيسية.", ["في النصائح افتح «معاينة» لرؤية النص المحفوظ. أثناء التعديل تظهر معاينة لما تكتبه.", "راجع اللغة والترتيب والنشاط والحالة، واكتب السبب واحفظ. المعاينة لا تنشر النص.", "في أقسام الصفحة الرئيسية افتح تعديل القسم لتغيير العنوان والمحتوى. وصف hero يظهر عند عدم وجود وصف للبانر الحالي.", "لإخفاء قسم منشور اضغط «إيقاف» واكتب السبب؛ يُحفظ غير نشط ويختفي من العرض العام.", "لإعادته استخدم «إعادة تشغيل» بسبب واضح. راجع الموقع بعد الحفظ؛ تغيير العرض لا يحذف النص المحفوظ."], [["الترتيب", "اختياري للنصائح: الفارغ يضيف الجديدة آخر القائمة، ويحفظ ترتيب القديمة. الأصغر أولاً."], ["المحتوى المنشور", "يتحدد بالنشاط وحالة النشر، وليس بمجرد وجود السجل."]], "نصائح قابلة للمعاينة وأقسام يمكن إيقاف عرضها وإعادته.", [["أريد صورة حملة للرئيسية؟", "استخدم البانرات للصور المجدولة، وليس خانة نصيحة أو عدد السكان."]], [{"label": "النصائح", "path": "/admin/content/tips"}, {"label": "محتوى الرئيسية", "path": "/admin/content/homepage"}, {"label": "البانرات", "path": "/admin/banners"}, {"label": "الرئيسية", "path": "/"}])
  ] },
  { id: 'banners', title: 'البانرات: الرفع والنشر والجدولة', description: 'دليل خطوة بخطوة مع حل تعارض المواعيد وإدارة الصورة والعرض.', topics: [
    topic('banner-create', 'إضافة بانر من البداية للنشر', 'رفع صورة حملة وتجهيز بياناتها ثم نشرها أو جدولتها.', 'صلاحية إدارة البانرات؛ يلزم تشغيل العرض ووجود صورة صالحة.', [], [['الموضع', 'مكان العرض؛ homepage.hero هو الموضع الرئيسي. ليس اسم ملف الصورة.'], ['الرابط المستهدف', 'رابط HTTPS للصفحة التي يفتحها الزائر، مثل https://elsadatrealestate.com/properties?lang=ar؛ قد يكون اختياريًا حسب الموضع.'], ['النص البديل', 'وصف الصورة لمستخدمي قارئ الشاشة؛ ليس رابطًا.'], ['موعد العرض', 'بداية ونهاية مع الوقت؛ 00:00 وقت افتراضي، لا تتركه دون مراجعة إذا أردت ساعة محددة.']], 'تُحفظ المسودة ثم تعتمد للنشر خلال موعدها، وتختفي عند النهاية تلقائيًا.', [['حفظت ولا يظهر البانر؟', 'اضغط نشر / جدولة، وتحقق من تشغيل العرض والصورة والموضع وبداية ونهاية الموعد.'], ['هل يجب فتح الإدارة عند موعد البداية؟', 'لا؛ العرض العام يتحقق من بداية ونهاية فترة البانر تلقائيًا. الصفحة المفتوحة تراجع البانرات في الخلفية كل 30 ثانية وعند الرجوع إليها، دون إعادة تحميل أو مسح اختيارات البحث.']], links(['إضافة بانر', '/admin/banners/new'], ['قائمة البانرات', '/admin/banners'], ['الرئيسية', '/'])),
    topic('banner-image', 'الصورة: الملف أو الرابط والأبعاد', 'اختيار صورة صالحة بدل مسار واتساب أو الكمبيوتر.', 'ملف مناسب أو رابط HTTPS مباشر لصورة متاحة.', [], [], 'تُقبل الوسائط وتظهر معاينة قابلة للمراجعة.', [['الرفع مرفوض؟', 'راجع الحجم والصيغة ونتيجة الفحص والأبعاد. لا تغيّر الامتداد فقط لتحويل صيغة الملف.']], links(['إضافة بانر', '/admin/banners/new'], ['إعدادات الإعلانات', '/admin/settings/advertising'])),
    topic('banner-manage', 'تعديل ومعاينة وإيقاف وأرشفة وترتيب البانرات', 'التحكم في الحملة بعد إنشائها.', 'صلاحية إدارة البانرات؛ راجع البانر المقصود قبل التنفيذ.', ['افتح القائمة واضغط تعديل بجانب البانر؛ عدّل الصورة أو العنوان أو الرابط أو الموعد، ثم احفظ قبل النشر.', 'استخدم المعاينة لفحص الشكل؛ معاينة المسودة لا تجعلها منشورة.', '«إيقاف العرض» يعيد البانر إلى مسودة لوقفه مؤقتًا.', '«أرشفة» تحتاج تأكيدًا وتُنهي استخدام هذا البانر؛ اختر الإيقاف إذا كنت تريد إعادة تشغيله لاحقًا.', 'استخدم أسهم الترتيب، ثم تحقق من الترتيب المحفوظ؛ تنقّل بين صفحات القائمة إذا كان العدد كبيرًا.', 'زر إيقاف جميع بانرات الرئيسية يوقف العرض العام دون حذف المسودات.'], [['مسودة', 'محفوظة وغير معروضة للعامة.'], ['مجدول', 'معتمد وبدايته مستقبلية.'], ['نشط', 'معتمد داخل الفترة؛ يتطلب تشغيل العرض.'], ['مؤرشف', 'متوقف نهائيًا لهذا السجل.']], 'تدير العرض مع التمييز بين الإيقاف المؤقت والأرشفة النهائية.', [['هل كل ضغط حفظ يعمل بانرًا جديدًا؟', 'في نفس النموذج يعيد الحفظ تعديل المسودة المحفوظة؛ لإنشاء حملة مستقلة افتح إضافة بانر جديد.']], links(['البانرات', '/admin/banners'], ['إضافة بانر', '/admin/banners/new'])),
    topic('banner-errors', 'البانر لا يظهر أو يوجد تعارض', 'فحص الأسباب بالترتيب بدل تغيير التواريخ عشوائيًا.', 'افتح بيانات البانر والقائمة بحساب الإدارة.', [], [], 'تحدد السبب الفعلي وتعيد النشر بموعد صحيح.', [['الحقول ما زالت تاريخًا ووقتًا في خانة واحدة؟', 'هذه علامة على نسخة أقدم من النموذج؛ يحتاج الموقع نشر التحديث. الدليل لا يغيّر النسخة الإنتاجية بنفسه.']], links(['البانرات', '/admin/banners'], ['إعدادات الإعلانات', '/admin/settings/advertising']))
  ] },
  { id: 'ads-commissions', title: 'الإعلانات والمدفوعات والعمولات', description: 'دورة الإعلان وإثباتات الدفع والسياسات والتخصيص والاستثناءات.', topics: [
    topic('ad-quote-schedule', 'إصدار عرض سعر إعلان ثم جدولته', 'تحديد السعر والفترة ثم متابعة الدفع والجدولة.', 'طلب إعلان أُحيل إلى التسعير؛ صلاحية إصدار العرض، ثم دفع معتمد وفترة متاحة للجدولة.', ['من طلبات الإعلانات اضغط عرض على الطلب. إذا كان قيد المراجعة، راجع المحتوى ثم اختر «إحالة إلى التسعير» مع السبب عند صلاحيته.', 'عندما يصبح بانتظار التسعير، اختر مكان العرض بالاسم والفترة بتوقيت مصر. في الطلب الجديد أدخل السعر بالجنيه؛ في الطلبات القديمة الحقل محدد بالقروش (100 قرش = جنيه). أكمل وصف البند وصلاحية العرض والشروط ثم أرسل العرض.', 'راجع المبلغ الظاهر بالجنيه بعد إصدار العرض قبل متابعة الدفع. ينتظر العرض قرار مقدم الخدمة قبل الانتقال للدفع.', 'راجع إثبات الدفع في قائمته واعتمده فقط بعد المطابقة. رفع الإثبات ليس اعتمادًا تلقائيًا.', 'من تفاصيل الطلب في مرحلة انتظار الدفع، استخدم جدولة الإعلان بعد اعتماد الإثبات وتأكد من توفر الفترة والموضع.', 'راجع التقويم وحالة الطلب بعد الجدولة؛ لا تعتبر إصدار عرض السعر نشرًا للإعلان.'], [['المبلغ بالقروش', 'هذه الخانة في عرض سعر الإعلان تستخدم القروش: 1000 جنيه = 100000 قرش. يختلف ذلك عن نموذج مبلغ العمولة الذي يطلب المبلغ بالوحدة المعروضة.'], ['صالح حتى', 'تاريخ ووقت انتهاء قبول العرض؛ أكمل الساعة والدقيقة في حقل التاريخ والوقت الحالي.'], ['وصف البند', 'ما يغطيه السعر؛ النموذج الحالي يصدر بندًا واحدًا بكمية 1 وعملة EGP.'], ['الشروط', 'شروط العرض الواضحة ومدته وما يشمله.']], 'ينتقل الإعلان من المراجعة إلى عرض سعر ثم دفع معتمد وجدولة وفق حالته الفعلية.', [['لا يظهر نموذج عرض السعر؟', 'يظهر في حالة بانتظار التسعير؛ راجع إحالة الطلب والصلاحيات.'], ['الجدولة تفشل؟', 'راجع اعتماد الدفع وتوفر الموضع والفترة وحالة الطلب وصلاحيتك، ثم افتح أحدث تفاصيله.']], links(['طلبات الإعلانات', '/admin/ads/requests'], ['مراجعة الدفع', '/admin/ads/payments/pending-review'], ['التقويم', '/admin/ads/calendar'])),
    topic('ad-requests', 'طلبات الإعلانات ودورة المراجعة', 'متابعة إعلان مقدم العقار بدل الخلط بينه وبين بانر الإدارة.', 'صلاحيات الإعلانات حسب خطوة القراءة أو المراجعة أو التسعير.', ['افتح طلبات الإعلانات وراجع وصف الطلب ورقم التواصل وصاحبه؛ الطلب الجديد يصل مباشرة قيد المراجعة.', 'راجع الإجراءات المتاحة في الحالة الحالية، مثل المراجعة أو عرض السعر أو المتابعة.', 'عند التسعير اختر مكان العرض بالاسم، وحدد البداية والنهاية بتوقيت مصر والسعر بالجنيه وشروط الدفع وصلاحية العرض. راجع المدة المحسوبة ثم أرسل عرض السعر.', 'عند وجود إثبات دفع، راجعه من قوائم الإثباتات قبل اعتبار الطلب مدفوعًا.', 'بعد قبول العميل واعتماد إثبات الدفع، جدول الطلب وراجع التقويم. جهز صورة البانر وعنوانه وفترته وانشره من البانرات؛ جدولة الطلب وحدها لا تنشئ صورة إعلان.'], [['طلب إعلان', 'طلب حملة مرتبط بمقدم الخدمة ومراجعتها وسدادها.'], ['بانر الإدارة', 'محتوى عرض تديره الإدارة من صفحة البانرات؛ ليس إثبات دفع.']], 'تنتقل الحملة في مراحلها المسموحة بدل نشر طلب غير مكتمل.', [['هل يوجد سعر موحد لكل الإعلانات؟', 'لا تفترض سعرًا عامًا؛ راجع العرض والموضع والقيم المعتمدة للطلب.']], links(['طلبات الإعلانات', '/admin/ads/requests'], ['تقويم الإعلانات', '/admin/ads/calendar'], ['البانرات', '/admin/banners'])),
    adPaymentsGuide,
    adPublicationGuide,
    topic('commission-policy', 'إنشاء سياسة عمولة ومعنى المفتاح', 'إعداد قاعدة عمولة بنسبة أو مبلغ أو إعفاء.', 'صلاحية إدارة العمولات؛ الحفظ الحالي ينشئ مسودة.', ['افتح إنشاء سياسة واكتب اسمًا واضحًا. المفتاح يتولد تلقائيًا من السيرفر عند الإنشاء.', 'اختر النوع: نسبة أو مبلغ ثابت أو إعفاء.', 'اختر النطاق. الافتراضي لا يحتاج مفتاح نطاق؛ باقي النطاقات تحتاج مرجع النوع أو الحساب أو المؤسسة الصحيح.', 'للنسبة أدخل 2.5 إذا كانت العمولة 2.5%؛ لا تكتب 250. للمبلغ أدخل قيمة المبلغ والعملة مثل EGP.', 'اختر تاريخ البداية المطلوب وتاريخ النهاية إن احتجت؛ النهاية بعد البداية، ثم احفظ وراجع رسالة المسودة.'], [['المفتاح', 'رمز تعريف فريد للسياسة، وليس كلمة مرور؛ يولد تلقائيًا عند الإنشاء ولا يُكتب يدويًا.'], ['النطاق', 'افتراضي، نوع مقدم، نوع معاملة، نوع عقار، مؤسسة أو حساب.'], ['مفتاح النطاق', 'القيمة المطابقة للنطاق؛ لا تكتب اسمًا تسويقيًا أو رقم هاتف بدل مرجع الحساب أو المؤسسة.'], ['الإعفاء', 'لا يتطلب قيمة نسبة أو مبلغ.']], 'تُحفظ سياسة مسودة، ويمكن مراجعة القائمة والسجل.', [['هل حفظ السياسة يغير العمولة فورًا؟', 'لا. لا تتعامل مع المسودة كسياسة فعالة؛ راجع عمولة الحساب الحالية ومصدرها.']], links(['سياسات العمولات', '/admin/commissions'], ['إنشاء سياسة', '/admin/commissions/new'], ['سجل العمولات', '/admin/commissions/history']), 'واجهة إنشاء السياسات الحالية تحفظ المسودات ولا توفر زر اعتمادها. اعتماد المسودات يحتاج استكمال واجهة البرنامج؛ لا يوجد إجراء مخفي يجب على الأونر البحث عنه.'),
    topic('commission-account', 'عمولة حساب معين والتعارض عند الحفظ', 'اختيار مقدم الخدمة بالاسم ومعرفة عمولته الفعلية.', 'صلاحية قراءة عمولة الحساب، وصلاحية الإدارة لإنشاء تخصيص.', ['افتح عمولة الحساب واختر مقدم الخدمة بالاسم؛ تنقل بين صفحات الاختيار إذا لم يظهر.', 'راجع السياسة الحالية ومصدرها وقيمتها وإصدارها، قبل إنشاء تخصيص جديد.', 'اختر نوع التخصيص والنسبة أو المبلغ والعملة، ثم البداية والنهاية واحفظ.', 'تكرار نفس البيانات ونفس البداية يعيد استخدام المسودة؛ لا تحتاج الضغط المتكرر.', 'إذا ظهر تعارض، فهناك بيانات مختلفة بنفس البداية أو سجل لم يعد مسودة. راجع السجل ولا تغيّر التاريخ إلا إذا قصدت تخصيصًا جديدًا بموعد جديد.'], [['اختيار الحساب', 'الاختيار بالاسم هو المسار المعتاد؛ المعرف اليدوي خيار إضافي فقط.'], ['مصدر العمولة', 'يوضح لماذا هذه القيمة هي المطبقة حاليًا؛ التخصيص الجديد المسودة لا يستبدلها فورًا.']], 'ترى العمولة الفعالة وتعرف نتيجة حفظ المسودة بوضوح.', [['لماذا accountId مطلوب؟', 'اختر مقدمًا من القائمة أولًا؛ الصفحة لا تفترض أي حساب عند فتحها دون اختيار.'], ['هل errors.conflict يعني احذف السياسة؟', 'لا. راجع البداية والبيانات والحالة. لا تستبدل سجلًا سابقًا أو تغير تاريخًا عشوائيًا.']], links(['عمولة حساب', '/admin/commissions/account'], ['السياسات', '/admin/commissions'], ['سجل العمولات', '/admin/commissions/history']), 'صفحة تخصيص الحساب الحالية لا توفر تعديل سجل سابق أو اعتماد المسودة من الواجهة. الحفظ وحده لا يفعّل التخصيص.'),
    topic('commission-exceptions', 'استثناءات العمولات والتأكيدات', 'تمييز الاستثناء للحساب عن السياسة العامة وتأكيد الاطلاع.', 'صلاحيات العمولات؛ يلزم معرّف حساب صحيح عند إنشاء الاستثناء.', [], [], 'تُوثق الاستثناءات والتأكيدات دون خلط بين معانيها.', [['أستخدم الاستثناء بدل التخصيص؟', 'اختر حسب القرار التجاري المقصود وراجع المصدر الفعال لعمولة الحساب؛ لا تنشئ أكثر من سجل لتجربة تجاوز خطأ.']], links(['الاستثناءات', '/admin/commissions/exceptions'], ['إنشاء استثناء', '/admin/commissions/exceptions/new'], ['التأكيدات', '/admin/commissions/confirmations']), 'لا تتوقع تفعيل مسودة عمولة بمجرد إنشائها؛ اعتمد على الحالة ومصدر العمولة الفعالة الظاهرين، ولا توجد واجهة اعتماد مسودات مكتملة حاليًا.')
  ] },
  { id: 'settings', title: 'إعدادات المنصة والصلاحيات والتدقيق', description: 'كل نطاقات الإعدادات وحسابات الإدارة والأدوار والسجلات.', topics: [
    topic("platform-contact", "معلومات المنصة والتواصل والحسابات الاجتماعية", "تحديث هوية المنصة ومعلومات التواصل العامة.", "صلاحية إدارة الإعدادات؛ اكتب سببًا واضحًا لكل حفظ.", ["افتح الإعدادات العامة واختر معلومات المنصة أو التواصل أو الحسابات الاجتماعية حسب ما تريد تغييره.", "راجع ملخص القيم المحفوظة قبل الكتابة؛ الاسم المحفوظ هو الاسم الحالي. إن لم يُحفظ اسم يظهر الاسم الافتراضي بدل حقل مجهول.", "غيّر الاسم بالعربية أو الإنجليزية. الحقول الاختيارية موضّحة، واللغة والعملة والمنطقة الزمنية لها قوائم اختيارات.", "في التواصل أدخل رقم واتساب المنصة. يقبل رقمًا مصريًا مثل 01012345678 أو دوليًا مثل +201012345678؛ اتركه فارغًا لإخفاء أزرار واتساب.", "في الاجتماعي أدخل رابط HTTPS الكامل لفيسبوك وإنستجرام؛ اترك الرابط فارغًا لإخفاء الأيقونة. فيسبوك أزرق وإنستجرام بتدرّجه وواتساب أخضر، وتظل ألوانها عند التفاعل.", "اكتب سببًا واحفظ النطاق. افتح الموقع للتحقق من الاسم والروابط. زر «اتصل بنا» في الفوتر يفتح واتساب المنصة."], [["رابط اجتماعي أو خريطة", "رابط الصفحة الفعلي؛ ليس اسم الحساب وحده أو رابط صورة."], ["البريد العام", "عنوان تواصل ظاهر؛ تعديله لا يغير إعداد خادم إرسال أكواد البريد."]], "هوية وتواصل محفوظان مع معرفة القيمة الحالية قبل تعديلها.", [["تعارض إعدادات؟", "أعد تحميل أحدث نسخة بعد الاحتفاظ بتعديلاتك؛ شخص آخر حفظ النطاق بعد تحميلك."]], [{"label": "كل الإعدادات", "path": "/admin/settings"}, {"label": "معلومات المنصة", "path": "/admin/settings/platform"}, {"label": "التواصل", "path": "/admin/settings/contact"}, {"label": "الاجتماعي", "path": "/admin/settings/social"}]),
    topic("property-request-settings", "إعدادات العقارات والطلبات", "مراجعة قواعد النشر والوسائط والتواصل والمتابعة المتاحة.", "صلاحية الإعدادات؛ غيّر فقط الحقول التي يعرضها النموذج.", ["راجع إعدادات نشر العقارات وحدود الوسائط المتاحة في النموذج.", "اضبط عدد الصور والحجم والصيغ وفق احتياج المنصة، واحفظ بسبب واضح.", "بيانات صاحب العقار في صفحة التواصل خاصة به وبالإدارة. لا توجد مفاتيح تسمح له بإظهارها للزوار.", "طلبات العملاء تمر عبر المنصة؛ بيانات الشركة العامة منفصلة عن بيانات التواصل الخاصة بالعقار.", "راجع إعدادات متابعة الطلبات والمواعيد المتاحة، واحفظ كل نطاق على حدة."], [["حدود الصور", "عدد الملفات وحجم كل ملف والصيغ المقبولة."], ["بيانات تواصل العقار", "خاصة بصاحب العقار والإدارة، ولا تظهر للعامة بعد النشر."]], "تُحفظ القواعد المتاحة مع سبب قابل للمراجعة.", [["هل إظهار تواصل المقدم متاح باشتراك؟", "لم يتم تفعيل قاعدة اشتراك لعرض بيانات اتصال صاحب العقار. بيانات الهاتف وواتساب والبريد والملاحظات الخاصة بالعقار مخفية عن الزوار؛ تواصل الشركات المنشور يخضع لإعدادات صفحة الشركة."]], [{"label": "إعدادات العقارات", "path": "/admin/settings/properties"}, {"label": "إعدادات الطلبات", "path": "/admin/settings/requests"}]),
    topic('advertising-settings', 'إعدادات الإعلانات والأبعاد وطرق الدفع', 'تجهيز مواضع الإعلان وصيغ الملفات والمقاسات.', 'صلاحية إعدادات الإعلانات؛ توافق القيم مع نوع الحملة.', ['راجع مواضع العرض وأنواع الإعلانات المدعومة.', 'راجع الأبعاد المطلوبة لسطح المكتب والتليفون، والصيغ المقبولة والحد الأقصى لحجم الملف.', 'راجع صلاحية عرض السعر وطرق إثبات الدفع المتاحة.', 'اكتب سبب التغيير واحفظ؛ أعد اختبار صورة بانر إذا تغيرت قيود المقاسات.'], [['الأبعاد', 'العرض والارتفاع بالبكسل؛ إدخال حجم الملف بالميجابايت هنا خطأ.'], ['طرق إثبات الدفع', 'تحدد أنواع الإثبات المقبولة، وليست تأكيدًا أن عملية دفع تمت.']], 'تصبح قواعد تجهيز الإعلان واضحة قبل رفع ملفات جديدة.', [['تشغيل البانرات؟', 'استخدم زر تشغيل العرض في صفحة البانرات ثم احفظ وانشر البانر؛ لا يكفي تغيير عنوان الصورة.']], links(['إعدادات الإعلانات', '/admin/settings/advertising'], ['البانرات', '/admin/banners'])),
    topic('seo-display', 'تحسين محركات البحث وإعدادات العرض', 'العناوين العامة والفهرسة واتجاه العرض والعداد.', 'صلاحية إدارة الإعدادات.', ['في SEO راجع عنوان الموقع والوصف الافتراضي وفاصل العنوان والنطاق الأساسي والسماح بالفهرسة وحالة خريطة الموقع وكود التحقق المتاح.', 'في العرض راجع اتجاه الصفحة وعدد النتائج وإظهار عداد السكان وقيمه التوضيحية حسب الحقول المتاحة.', 'احفظ بسبب واضح ثم اختبر الصفحة العامة بالعربية والإنجليزية.', 'راجع مصدر رقم السكان من إدارة العداد؛ لا تستخدم إعداد العرض لاختراع رقم بلا مصدر.'], [['النطاق الأساسي', 'الدومين المقصود للفهرسة؛ لا تدخل رابط ملف أو صفحة عشوائية.'], ['الفهرسة', 'السماح بمحركات البحث؛ لا يضمن الظهور أو ترتيبًا معينًا فورًا.']], 'تُحفظ قيم العناوين والعرض دون وعد بنتيجة بحث فورية.', [['هل عدد النتائج يغيّر عدد العقارات الحقيقي؟', 'لا؛ يغير حجم الصفحة فقط.']], links(['SEO', '/admin/settings/seo'], ['العرض', '/admin/settings/display'], ['عداد السكان', '/admin/content/population-counter'])),
    topic('privacy', 'الخصوصية والأمان وقواعد المجتمع', 'مراجعة بيانات التواصل والوثائق والجلسات وضوابط المحتوى.', 'صلاحية إعدادات الخصوصية والأمان؛ لا تدخل أسرارًا في سبب التغيير.', ['راجع إخفاء بيانات العميل والملاحظات الداخلية والوثائق الخاصة وفق القيم المتاحة.', 'راجع مدة جلسة الإدارة والمصادقة الثنائية المعروضة؛ وجود إعداد لا يغني عن تجهيز تدفق الدخول المناسب.', 'راجع الكلمات المحظورة وإجراء اكتشافها وحد المنشورات اليومي ووقت انتظار المراجعة عند وجود هذه الحقول.', 'احفظ ثم اختبر بحساب محدود الصلاحية؛ لا تعتمد على إخفاء زر وحده لحماية البيانات.'], [['الكلمات المحظورة', 'كلمة في كل سطر وفق النموذج؛ تحتاج مراجعة تمنع حجب محتوى سليم بالخطأ.'], ['الوثائق الخاصة', 'لا تنقل روابطها لمحتوى عام أو دليل منشور.']], 'تكون قواعد الخصوصية والمراجعة موثقة.', [['هل فلتر الكلمات يلغي مراجعة البلاغات؟', 'لا؛ البلاغات والمراجعة البشرية تظل ضرورية.']], links(['الخصوصية والأمان', '/admin/settings/privacy-security'], ['بلاغات المجتمع', '/admin/community/moderation'])),
    topic("admin-users-roles", "مستخدمو الإدارة والأدوار والصلاحيات", "منح صلاحيات العمل بدل مشاركة حساب مدير واحد.", "صلاحية إدارة مستخدمي الإدارة أو الأدوار؛ بعض الحمايات تمنع تعطيل آخر مسؤول أعلى.", ["أنشئ المنصب من الأدوار والصلاحيات وحدّد ما يستطيع الموظف عرضه أو تغييره.", "من مستخدمي الإدارة أضف الموظف باسمه وإيميله وكلمة مرور قوية. اختَر مسؤولًا قياسيًا والمنصب المناسب؛ المسؤول الأعلى يدير المنصة بالكامل.", "لو ظهرت رسالة إن الإيميل مستخدم، اضغط «البحث عن الحساب الإداري بهذا الإيميل». إن كان موجودًا افتحه وعدّل صلاحياته. لو الإيميل لحساب عميل أو مقدم عقار، استخدم إيميلًا آخر للموظف.", "خطأ الحفظ لا يمسح البيانات المكتوبة؛ صحّح الإيميل أو المنصب ثم أعد الحفظ. إنشاء حساب مكرر لا يعدّل صلاحيات الحساب القديم.", "بعد نجاح الإنشاء افتح حساب الموظف وراجع المنصب، ثم سلّمه رابط تسجيل الدخول المعتاد وإيميله وكلمة مروره عبر وسيلة مناسبة.", "يستخدم الموظف إيميله وكلمة المرور ويكمل تحقق الإدارة المعتاد. اختبر حسابه في جلسة منفصلة؛ قراءة الدليل أو اختيار قسم فريق العمل لا يمنحه صلاحيات."], [["عرض فقط", "قراءة دون تعديل."], ["دور مخصص", "مجموعة صلاحيات محددة، وليس اسمًا يفتح كل الصفحات تلقائيًا."], ["المسؤول الأعلى", "مستوى واسع الصلاحيات يحتاج تخصيصًا مدروسًا."]], "موظف بحساب مستقل وصلاحيات واضحة ورابط دخول معروف.", [["الدور حساب مستقل؟", "لا. الدور مجموعة صلاحيات تُربط بحساب موظف له إيميل وكلمة مرور."], ["ظهر errors.conflict أثناء إضافة حساب؟", "النسخة المحدّثة توضّح تعارض الإيميل أو المنصب. الإيميل المستخدم لا ينشئ حسابًا جديدًا ولا يغيّر الحساب الموجود."]], [{"label": "مستخدمو الإدارة", "path": "/admin/admin-users"}, {"label": "إضافة مسؤول", "path": "/admin/admin-users/new"}, {"label": "الأدوار", "path": "/admin/roles"}]),
    topic("notifications-audit", "الإشعارات وسجل التدقيق", "متابعة أحداث النظام ومعرفة من غيّر البيانات.", "صلاحية قراءة إشعارات الإدارة أو سجل التدقيق.", [], [["التدقيق", "تاريخ إجراءات الإدارة، مختلف عن رسالة عميل."], ["الإشعار", "تنبيه داخل النظام؛ وجوده لا يعني أن بريدًا خارجيًا وصل."]], "تمييز التنبيه عن سجل التغييرات والوصول إلى الحدث المطلوب بسهولة.", [["هل يمكن تعديل سجل التدقيق؟", "لا تتعامل معه كمحتوى قابل للتحرير؛ يحفظ أثر العمليات للتحقق."]], [{"label": "الإشعارات", "path": "/admin/notifications"}, {"label": "سجل التدقيق", "path": "/admin/audit-logs"}])
  ] },
  { id: 'visitor-seeker', title: 'الزائر والباحث عن عقار', description: 'دليل دعم العميل: البحث والمقارنة والتسجيل والطلبات والملف.', topics: [
    topic('public-search', 'البحث والفئات والفلاتر والمقارنة', 'الوصول لعقار مناسب في الموقع العام.', 'يمكن للزائر البحث؛ بعض الإجراءات تحتاج تسجيل الدخول كباحث.', ['افتح الرئيسية واختر بيعًا أو إيجارًا ونوع العقار والمنطقة والسعر ثم ابحث.', 'اختيار بطاقة فئة يفتح نتائجها؛ زر العودة أو مسح الفئة يعيدك للعرض الأوسع.', 'في التليفون افتح أو اطوِ التصفية، وحدد النوع والمنطقة وحالة الاستلام ونطاق السعر ثم طبّق.', 'بدّل شبكة أو قائمة حسب العرض المناسب؛ ترتيب النتائج لا يغيّر بيانات العقار.', 'أضف العقارات للمقارنة وافتح شريط المقارنة من الصفحات العامة؛ احذف عنصرًا لإفساح مكان عند بلوغ الحد المعروض.', 'افتح بطاقة العقار لقراءة السعر والمعاملة وخطة السداد والصور والموقع، لا تستنتج السعر من صورة العقار.', 'في صفحة المطورين، شريط البحث فوق البطاقات يقبل اسم الشركة أو جزءًا منه بالعربية أو الإنجليزية. اضغط بحث أو Enter؛ إعادة ضبط يمسح البحث ويعرض الشركات مجددًا. يظل الشريط متاحًا عند عدم وجود نتائج لتجربة اسم آخر.', 'داخل ملف المطور، أزرار نبذة والمشروعات والوحدات المتاحة والتواصل تنقلك بسكرول ناعم للقسم نفسه، وتظل عناوين الأقسام ظاهرة تحت التبويبات دون إعادة تحميل الصفحة أو مسح الحقول المكتوبة؛ الرجوع يحافظ على مكانك. إذا فعّلت تقليل الحركة في جهازك، ينتقل القسم مباشرة.', 'قسم التواصل يعرض المعلومات العامة المنشورة فقط. إذا لم ينشر المطور هاتفًا أو عنوانًا أو واتساب، تظهر رسالة عدم توفر بيانات التواصل؛ فتح القسم ليس إرسال طلب.'], [['نطاق السعر', 'حد أدنى وأقصى؛ الأعلى لا يقل عن الأدنى، وتُراعى المعاملة.'], ['المقارنة', 'قائمة على هذا الجهاز بحسب تخزين المتصفح؛ ليست رسالة للمقدم.']], 'تظهر النتائج المناسبة وتقارن عناصرها.', [['المقارنة اختفت؟', 'راجع نفس المتصفح، وعدم مسح بيانات الموقع، وعدد العناصر المختارة.'], ['الأرقام على الفئات؟', 'عدد العقارات المنشورة المتاحة، وليس عدد وحدات المدينة.']], links(['الرئيسية', '/'], ['العقارات', '/properties'], ['المقارنة', '/compare'], ['المطورون', '/developers'])),
    topic('seeker-register', 'تسجيل الباحث ورمز التحقق', 'إنشاء حساب وتفعيل البريد.', 'بريد صحيح يمكن لصاحبه الوصول إليه؛ لا تشارك رمز التحقق.', ['افتح إنشاء حساب واختر باحثًا ثم اضغط متابعة؛ اختيار نوع الحساب وحده لا يكمل التسجيل.', 'أكمل بيانات التسجيل المطلوبة وراجع البريد قبل إرسال الطلب.', 'افتح رسالة التحقق، واكتب الرمز في الصفحة المخصصة قبل انتهاء صلاحيته.', 'إذا لم تصل الرسالة، افحص البريد غير الهام والعنوان وانتظر الوقت المعروض قبل إعادة الإرسال.', 'بعد اكتمال التسجيل أو تسجيل الدخول تفتح الرئيسية لكل أنواع الحسابات. افتح «حسابي» للوصول للوحة حسابك والطلبات والمعاينات. رابط دخول قديم لا يعيدك للمعاينات تلقائيًا. إذا أعاد المتصفح فتح تبويب معاينات محفوظ، افتح رابط الرئيسية أو زر البحث أعلى لوحة الباحث؛ كلمة المرور والرمز لا يُرسلان للإدارة في بلاغ دعم.'], [['الرمز', 'رمز مؤقت للبريد والغرض الحالي؛ إعادة الإرسال قد تجعل الرمز السابق غير مناسب.'], ['التحقق', 'مختلف عن اعتماد أوراق مقدم العقار.']], 'يتحقق البريد ويمكن تسجيل الدخول بدور الباحث.', [['الرمز لا يصل مرة واحدة؟', 'تحقق من العنوان والبريد غير الهام والمهلة. عند تكرار المشكلة سجّل وقت المحاولة والبريد في قناة الدعم الخاصة، دون إرسال كلمات مرور أو رمز.']], links(['اختيار الحساب', '/auth/register'], ['تسجيل باحث', '/auth/register/seeker'], ['تسجيل الدخول', '/auth/login'])),
    topic("seeker-requests", "لوحة الباحث وطلب التواصل والمعاينة", "إرسال طلب حقيقي ومتابعته.", "حساب باحث مسجل ومتحقق؛ استخدم جلسته عند الاختبار.", ["افتح العقار واختر طلب التواصل أو المعاينة. سجّل الدخول بحساب باحث إذا طُلب منك ذلك.", "أكمل الاسم ورقم الهاتف والرسالة، وللمعاينة اختَر موعدًا مستقبليًا بتوقيت مصر. اضغط الإرسال وانتظر رسالة النجاح.", "من الإشعارات اضغط الكارت أو الأيقونة أو «فتح التفاصيل». راجع الحالة وآخر رسالة؛ افتح الرسائل السابقة للتاريخ.", "إذا ظهرت «يحتاج معلومات»، اقرأ المطلوب واكتب المعلومات في نموذج الرد داخل نفس الطلب ثم أرسلها. لا تحتاج بدء طلب جديد لاستكماله.", "لو تريد طلبًا مختلفًا استخدم «بدء طلب جديد» من التفاصيل واكتب بياناته؛ يحتفظ الطلب القديم بسجل المتابعة.", "لو تعذر الإرسال، راجع الرسالة المحددة والاتصال والجلسة؛ البيانات تظل في النموذج. واتساب المنصة وسيلة تواصل بديلة."], [["طلب التواصل", "طلب متابعة وليس إتمام شراء."], ["المعاينة", "طلب موعد؛ قد يحتاج تأكيدًا أو إعادة جدولة."]], "طلب محفوظ يمكن استكمال بياناته ومتابعته من حساب الباحث.", [["هل الضغط على التواصل يحجز العقار؟", "لا؛ هو بدء متابعة. الحجز أو الاتفاق التجاري ليس تلقائيًا بمجرد إرسال الطلب."]], [{"label": "لوحة الباحث", "path": "/seeker"}, {"label": "طلباتي", "path": "/seeker/requests"}, {"label": "معايناتي", "path": "/seeker/viewings"}, {"label": "إشعارات الباحث", "path": "/seeker/notifications"}]),
    topic('seeker-profile', 'المحفوظات والملف والتفضيلات والإعدادات', 'تحديث بيانات الباحث وقائمته الشخصية.', 'جلسة باحث؛ هذه الروابط لا تحوّل حساب الإدارة إلى باحث.', ['احفظ العقار من بطاقته أو تفاصيله وراجعه في المحفوظات.', 'عدّل البيانات الشخصية من الملف، واحتياجات البحث من تبويب التفضيلات، ثم احفظ.', 'في الإعدادات اختر لغة الحساب أو بيانات الأمان وفق الحقول المتاحة.', 'راجع التأكيد بعد الحفظ؛ اللغة المفضلة تختلف عن ترجمة محتوى العقارات.'], [['المحفوظات', 'قائمة حسابك؛ مختلفة عن قائمة المقارنة.'], ['التفضيلات', 'احتياجك للبحث، وليس تغييرًا لبيانات عقار منشور.']], 'تُحفظ بيانات وتفضيلات الحساب المناسب.', [['هل الإعدادات تعدل بيانات المكتب؟', 'لا؛ إعدادات الباحث تخص حساب الباحث.']], links(['المحفوظات', '/seeker/saved'], ['الملف الشخصي', '/seeker/profile?tab=personal'], ['التفضيلات', '/seeker/profile?tab=preferences'], ['إعدادات الباحث', '/seeker/settings'])),
    topic('public-content', 'المقالات والمجتمع وصفحات التعريف', 'قراءة المحتوى والإبلاغ عن المخالفات.', 'التصفح العام متاح؛ إرسال منشور أو بلاغ يخضع لحالة الدخول.', ['افتح المقالات واضغط أي جزء قابل للفتح من البطاقة لقراءة المقال.', 'افتح المجتمع لقراءة المنشورات؛ عند الإنشاء اكتب محتوى مناسبًا وأرسله للمراجعة.', 'استخدم إبلاغ عند وجود مخالفة، واختر السبب وأكمل التفاصيل المطلوبة.', 'راجع من نحن وفريق العمل لمعرفة بيانات المنصة المنشورة.'], [['المنشور المرسل', 'قد ينتظر المراجعة قبل الظهور.'], ['التعليقات', 'غير متاحة للجمهور؛ لا يوجد نشر تعليقات جديدة.']], 'يصل المحتوى والبلاغ للمسار المناسب.', [['هل بلاغي ظاهر لكل الناس؟', 'لا تنشر معلومات خاصة في نص المنشور؛ استخدم نموذج البلاغ الذي تراجعه الإدارة.']], links(['المقالات', '/articles'], ['المجتمع', '/community'], ['من نحن', '/about'], ['الفريق', '/team']))
  ] },
  { id: 'provider', title: 'الفرد والمكتب وشركة التطوير', description: 'التسجيل والمستندات ولوحة المقدّم وإضافة العقارات والعملاء.', topics: [
    topic('provider-register', 'تسجيل مقدم عقار حسب نوعه', 'اختيار فرد أو مكتب وساطة أو شركة تطوير بشكل صحيح.', 'بريد فعّال ومستندات وبيانات تخص النوع الحقيقي للحساب.', ['من إنشاء حساب اختر مقدم عقار ثم متابعة، وحدد نوعه.', 'أكمل بيانات الحساب والبريد والتحقق حسب التدفق الظاهر.', 'في المكتب أدخل الاسم القانوني والتجاري والعنوان والسجل التجاري والتسجيل الضريبي والممثل المفوض وصفته وصلاحية صاحب الحساب حسب المطلوب.', 'في شركة التطوير أدخل بيانات الشركة وممثلها ومستنداتها؛ لا تختَر مطورًا لمجرد الحصول على تبويب مشروعات.', 'احفظ المسودة إذا احتجت إكمالًا لاحقًا، ثم أكمل الخطوات المطلوبة قبل إرسال المراجعة.'], [['الاسم القانوني', 'الاسم المسجل رسميًا، مختلف عن الاسم التجاري المعروض.'], ['الممثل المفوض', 'الشخص صاحب صلاحية تمثيل المنشأة وصفته؛ ليس اسم مسؤول الموقع.']], 'تُحفظ بيانات النوع الصحيح ويصبح الطلب جاهزًا لإكمال المستندات.', [['البيانات لا تُحفظ؟', 'راجع الحقول المطلوبة والرسالة وحالة الجلسة. لا تكرر إنشاء حساب آخر لنفس البريد لتجاوز الخطأ.']], links(['اختيار نوع مقدم', '/auth/register/provider/type'], ['حساب مكتب', '/auth/register/provider/account?providerType=brokerage_office&step=organization'], ['حساب مطور', '/auth/register/provider/account?providerType=developer_company&step=organization'])),
    topic('provider-documents', 'المستندات ومراجعة الطلب والنواقص', 'إكمال الطلب بدون فقد الملفات المرفوعة.', 'الدخول بحساب مقدم الطلب؛ الملفات واضحة وصيغها وأحجامها مقبولة.', ['افتح خطوة المستندات وارفع المستند لكل خانة تخص نوع الحساب، وانتظر اكتمال الرفع والفحص.', 'أكمل الحقول الإضافية المطلوبة مثل الموقع الرئيسي وبيانات المؤسسة وصلاحية صاحب الحساب.', 'راجع قائمة النواقص الظاهرة؛ المستندات المرفوعة وحدها لا تكمل البيانات القانونية.', 'احفظ ثم انتقل للمراجعة عند اكتمال المتطلبات، وراجع البيانات قبل الإرسال النهائي.', 'بعد الإرسال تظهر رسالة استلام الطلب وتبقى في شاشة المتابعة دون تسجيل خروج. يمكنك الدخول بنفس البريد وكلمة المرور أثناء المراجعة؛ أدوات إضافة العقارات والمشروعات والإعلانات تظل مقفولة حتى اعتماد الورق.', 'من لوحة العارض اضغط متابعة حالة الطلب أو تحديث حالة الطلب. إذا طلبت الإدارة معلومات، افتح استكمال الطلب وعدّل النواقص ثم أعد الإرسال. الموافقة أو طلب الاستكمال يحدّثان الحالة دون طردك من الحساب؛ الرفض أو الإيقاف يمنعان الوصول.'], [['صلاحية مسجلة لصاحب الحساب', 'اختيار نعم أو لا وفق الواقع؛ لا تُترك بلا إجابة عند طلبها.'], ['حالة الملف', 'انتظار الفحص أو رفضه يختلف عن اكتمال الرفع.']], 'يصل طلب كامل للإدارة ويحافظ على الملفات المقبولة.', [['أرسلت الأوراق ولا أقدر أراجع؟', 'اقرأ كل اسم في قائمة النواقص وأكمل بياناته؛ راجع حفظ خطوة المؤسسة ثم المستندات.'], ['«المسار غير متاح»؟', 'افتح التدفق الحالي من التسجيل بحسابك بدل رابط خطوة قديم أو جلسة إدارة.']], links(['مستندات المكتب', '/auth/register/provider/account?providerType=brokerage_office&step=documents'], ['مستندات المطور', '/auth/register/provider/account?providerType=developer_company&step=documents'], ['لوحة مقدم العقار', '/provider'], ['متابعة الاعتماد', '/provider-application/status'])),
    topic('contact-routing', 'التواصل مع شركة مباشرة أو عن طريق المنصة', 'اختر جهة الطلب وأرسله وتابع الرد من حسابك.', 'إرسال النموذج يحتاج حساب باحث عن عقار. الواتساب والاتصال المتاحان لا يحتاجان تسجيل الدخول.', ['من صفحة الشركة أو العقار اختر جهة التواصل: الشركة مباشرة أو إدارة عقارات السادات كوسيط.', 'أدخل اسمك وهاتفك ووقت التواصل ورسالتك، ثم أرسل. تظهر رسالة نجاح وتظل البيانات في النموذج.', 'الطلب المباشر يصل للشركة في طلبات العملاء ومعه إشعار. الشركة تغيّر الحالة ويمكنها كتابة رسالة تصل للعميل في الطلب والإشعارات.', 'طلب الوساطة يصل للإدارة ولا يضاف تلقائياً إلى صندوق الشركة. تابع الحالة والرسائل من طلباتي.', 'الواتساب والاتصال الخارجي لا يسجلان طلباً داخل النظام. استخدم النموذج لو تحتاج متابعة موثقة.'], [['جهة التواصل', 'الشركة مباشرة أو إدارة المنصة كوسيط.'], ['الشركة', 'يقبل النظام الشركات المعتمدة ويتحقق من هوية صاحبها على الخادم؛ لا تختار معرف مستخدم يدويًا.']], 'طلب محفوظ لدى الجهة المختارة ويمكن متابعة الحالة والرد.', [['هل يوجد اشتراك مدفوع يفتح التواصل؟', 'التواصل الحالي مرتبط باعتماد الشركة وإعدادات نشر معلوماتها؛ لا يوجد شرط اشتراك مدفوع مستقل في هذا المسار. طلبات الإعلانات والتسعير مسار منفصل.']], links(['الشركات', '/developers'], ['طلباتي', '/seeker/requests'], ['طلبات العملاء للشركة', '/provider/customer-requests'], ['طلبات التواصل للإدارة', '/admin/contact-requests'])),
    topic('egypt-viewing-time', 'مواعيد المعاينة بتوقيت مصر', 'الوقت بتوقيت مصر مهما كان توقيت جهازك.', 'اختر موعدًا مستقبليًا مع التاريخ والساعة.', ['اكتب الساعة بتوقيت مصر. يستخدم النظام Africa/Cairo ويحسب GMT+2 شتاءً أو GMT+3 صيفاً تلقائياً بحسب تاريخ الموعد.', 'لا تكتب اسم مدينة أو توقيت أوروبي. الشركة المسؤولة تؤكد الموعد أو تعيد جدولته من طلبات المعاينة. الإدارة تفتح «عرض» لمراجعة بيانات المعاينة والعقار وملاحظة العميل؛ فتح التفاصيل يميز التنبيه كمقروء.', 'طلب المعاينة الجديد يشعر مقدم العقار، والتأكيد أو إعادة الجدولة أو الإلغاء أو اكتمال المعاينة يشعر الطرف الآخر. بعد الإرسال تظهر رسالة نجاح ولا تختفي بيانات النموذج عند تجديد الجلسة.', 'إذا تعذر الاتصال مؤقتاً أعد المحاولة. انقطاع الشبكة لا يسجل خروجك؛ الجلسة الملغاة أو المنتهية فعلياً تحتاج تسجيل دخول جديد.'], [['التوقيت', 'توقيت مصر محسوب تلقائياً؛ خانة للعرض فقط.']], 'موعد محفوظ بتوقيت مصر مع إمكانية متابعته وتعديله حسب صلاحيات حسابك.', [['هل أستخدم توقيت جهاز خارج مصر؟', 'لا؛ اكتب الوقت الذي تريد المعاينة فيه داخل مصر.']], links(['معايناتي', '/seeker/viewings'], ['معاينات الشركة', '/provider/viewings'])),
    topic('property-video', 'صور العقار والفيديو', 'رفع فيديو للعقار بجانب الصور وعرضه للزائر بعد النشر.', 'حساب مقدم عقار معتمد يملك المسودة؛ التعديل متاح للمسودة أو العقار المطلوب تعديله.', ['افتح عقاراتي واختر إضافة عقار أو متابعة المسودة، ثم خطوة الصور والوسائط.', 'استخدم اختيار صورة لملفات JPG أو PNG، واختيار فيديو لملف MP4، واختيار مخطط لملف PDF. الحد الأقصى 10 ميجابايت لكل ملف؛ يفضل فيديو H.264 مع صوت AAC ليعمل على الموبايل.', 'انتظر انتهاء الرفع وظهور اسم الملف، ثم رتّب الوسائط أو أزل الملف الخطأ. قائمة الملفات تبقى محفوظة عند إعادة فتح المسودة.', 'أكمل بيانات التواصل والمراجعة وأرسل العقار للمراجعة؛ رفع الفيديو وحده لا ينشر العقار.', 'بعد نشر العقار افتح تفاصيله واضغط المصغّر الذي يحمل علامة التشغيل، ثم شغّل الفيديو من عناصر التحكم. لا يعمل تلقائيًا ولا يحل مكان صورة الغلاف.', 'إذا كان الفيديو أكبر من الحد، قلّل مدته أو اضغطه إلى MP4. إذا ظهرت مشكلة تشغيل، استخدم H.264/AAC ثم أعد رفعه.'], [['MP4', 'ملف فيديو من الجهاز، وليس رابط يوتيوب.'], ['نشر الفيديو', 'يتبع نشر العقار؛ لا يظهر فيديو مسودة أو ملف محذوف للزوار.']], 'يبقى الفيديو محفوظًا مع صور العقار ويعرضه مشغّل داخل صفحة العقار المنشور.', [['هل يمكن استخدام الفيديو كغلاف؟', 'لا؛ صورة الغلاف يجب أن تكون صورة.'], ['أين أرفع الفيديو؟', 'من خطوة الصور والوسائط في مسودة العقار، بزر اختيار فيديو.']], links(['عقاراتي', '/provider/properties'], ['إضافة عقار', '/provider/properties/new/basic'])),
    topic('provider-access', 'لوحة مقدم العقار قبل وبعد الاعتماد', 'فهم قيد المراجعة وتوفر الصفحات حسب النوع.', 'حساب مقدم متحقق؛ الاعتماد الإداري مطلوب للوظائف الكاملة.', ['افتح لوحة المقدّم وراجع حالة الطلب أولًا.', 'إذا كان قيد المراجعة، لا تعيد التسجيل؛ أكمل فقط ما تطلبه الإدارة.', 'بعد الاعتماد حدّث الصفحة أو سجل الدخول مجددًا عند الحاجة، ثم راجع العقارات والإعدادات.', 'المكتب والفرد يستخدمان العقارات؛ المشروعات لشركات التطوير ولا ينبغي اعتبار غيابها فقدان دخول.', 'من الإعدادات راجع الحساب والتواصل والأمان واحفظ كل تغيير مع التأكيد المتاح.'], [['الموافقة', 'اعتماد طلب مقدم الخدمة، مختلفة عن التحقق بالبريد أو نشر كل عقاراته.']], 'تعرف ما المتاح وما ينتظر المراجعة.', [['كل صفحة تقول يلزم تسجيل الدخول؟', 'راجع الجلسة والدور والاعتماد. إذا انتهت الجلسة ادخل بالحساب الصحيح؛ لا تحاول تعطيل الحماية.']], links(['لوحة مقدم العقار', '/provider'], ['عقاراتي', '/provider/properties'], ['المشروعات للمطور', '/provider/projects'], ['الإعدادات', '/provider/settings'])),
    topic('provider-property', 'إضافة عقار: الخطوات الثماني', 'تجهيز عقار كامل قبل الإرسال للمراجعة.', 'مقدم معتمد؛ بيانات المؤسسة تُؤخذ من الجلسة ولا تُختلق في النموذج.', ['البيانات الأساسية: أدخل اسم العقار ونوع السجل والمعاملة. رابط العقار يتولد تلقائيًا عند الإنشاء.', 'الموقع: اختر المنطقة وأكمل العنوان وبيانات الموقع المطلوبة.', 'التفاصيل: اختر نوع العقار من القائمة وأدخل المساحة والغرف والوصف والطابق. الطابق لا يتجاوز إجمالي طوابق المبنى؛ مثلًا الطابق 3 يحتاج إجمالي 3 أو أكثر. الخطأ يحدد الحقل، وتظل بياناتك مكتوبة لتصحيحها والحفظ.', 'السعر والسداد: أدخل السعر والعملة ونوع السداد والدفعات أو الإيجار وفق المعاملة.', 'المميزات والخدمات اختيارية بالكامل: ضع علامة أمام ما يتوفر فعلًا بالعقار أو بالقرب منه، مثل المصعد أو الحديقة أو المدارس بحسب القوائم المتاحة. لا تكتب أسماء أو أكواد. يمكنك الحفظ أو المتابعة بدون اختيار أي شيء؛ وتستطيع إلغاء العلامة عند التعديل.', 'الصور والوسائط: ارفع ملفات واضحة بالصيغ والأحجام المقبولة وانتظر نتائج الرفع.', 'التواصل: راجع بيانات الشخص أو الجهة المتاحة للمتابعة.', 'المراجعة والإرسال: راجع الخطوات كلها، احفظ المسودة أو أرسل الطلب حسب الزر المتاح.'], [['مصدر العقار والمؤسسة', 'مرتبطان بهوية المقدّم في الجلسة؛ لا تُدخل معرّفات عشوائية.'], ['المشروع', 'اختياري عند ارتباط الوحدة بمشروع مطور متاح؛ لا يلزم مكتبًا لإنشاء مشروع.'], ['المعرّف المختصر', 'جزء رابط العقار؛ يتولد تلقائيًا ويظل ثابتًا عند تعديل الاسم، وليس معرّف المؤسسة.']], 'يُحفظ العقار مسودة أو يُرسل للمراجعة؛ الإرسال ليس نشرًا تلقائيًا.', [['نوع المصدر غير متاح؟', 'راجع اعتماد الحساب والجلسة ونوع مقدم الخدمة؛ هذه بيانات هوية وليست نصًا حرًا.'], ['لماذا لم يظهر عقاري؟', 'راجع حالته: مسودة أو مرسل أو مرفوض أو منشور، وسبب الرفض أو طلب التعديل.']], links(['إضافة عقار', '/provider/properties/new/basic'], ['عقاراتي', '/provider/properties'])),
    topic('provider-followup', 'العملاء والمعاينات والإعلانات والعمولة', 'متابعة الطلبات الخاصة بالمقدم والسياسة المطبقة.', 'جلسة مقدم معتمد وصلاحيات النوع المناسب.', ['افتح طلبات العملاء لقراءة الطلب أو إنشاء طلب عميل عند توفر الإجراء، وراجع بياناته قبل الحفظ.', 'راجع المعاينات ومواعيدها وحالاتها؛ لا تفترض تأكيد كل موعد بمجرد الطلب.', 'في الإعلانات اضغط طلب إعلان، وأدخل رقم التواصل ووصف ما تريد الإعلان عنه ثم أرسل. لا تحتاج كود مكان العرض أو تواريخ؛ تتواصل الإدارة لتحديد السعر والفترة، ثم تقبل العرض وترفع إثبات الدفع.', 'في العمولة راجع السياسة الحالية ومصدرها وقيمتها وتاريخ سريانها، ثم أكد الاطلاع إذا كان الإجراء متاحًا.', 'راجع الإشعارات للمتابعة؛ المقدّم لا يستطيع تغيير سياسة عمولته من حسابه.'], [['تأكيد العمولة', 'تأكيد قراءة السياسة، وليس دفعها أو تعديلها.'], ['طلب العميل', 'سجل متابعة يحتاج بيانات صحيحة، لا وعد بإتمام صفقة.']], 'تُتابع الطلبات والإعلانات وتفهم العمولة المطبقة.', [['طلبت نسبة جديدة ولم تتغير؟', 'التخصيص الإداري المسودة لا يفعّل نفسه؛ الإدارة تراجع المصدر الفعال والحالة.']], links(['طلبات العملاء', '/provider/customer-requests'], ['المعاينات', '/provider/viewings'], ['الإعلانات', '/provider/ads'], ['العمولة', '/provider/commission'], ['الإشعارات', '/provider/notifications']))
  ] },
  { id: 'help', title: 'حل المشكلات وقائمة المراجعة اليومية', description: 'تمييز الخطأ من حالة العمل وتجهيز بلاغ دعم مفيد.', topics: [
    topic('errors', 'رسائل الخطأ: ماذا أفعل الآن؟', 'خطوات عملية للحالات الشائعة دون تغيير بيانات عشوائي.', 'احتفظ بالنص الذي كتبته وبالرابط قبل إعادة تحميل صفحة بها تعديلات.', ['يلزم تسجيل الدخول: ادخل بحساب الدور الصحيح، وتحقق من انتهاء الجلسة واعتماد مقدم الخدمة.', 'الوصول غير مسموح: راجع دور الإدارة وصلاحية المهمة؛ لا تكرر الضغط أو تغير معرف السجل للتجاوز.', 'السجل غير موجود أو 404: افتح الصفحة من القائمة، وحدد السجل من النتائج؛ قد يكون الرابط قديمًا أو السجل أزيل.', 'تعارض: راجع أحدث السجل أو المسودة الموجودة؛ لا تستبدل تعديل مسؤول آخر ولا تغير موعدًا لتجاوز القيد.', 'تاريخ غير صالح: أكمل كل أجزاء التاريخ والوقت المطلوبة، واجعل النهاية بعد البداية. البانر يحتوي تاريخًا ووقتًا منفصلين، وتاريخ السكان والعمولة تاريخ فقط.', 'تعذر الاتصال: انتظر ثم أعد المحاولة من الزر؛ قبل إعادة إرسال عملية حفظ تحقق هل ظهرت نتيجتها في القائمة.'], [['مسودة', 'تم الحفظ لكن لم يحدث نشر أو اعتماد.'], ['قيد المراجعة', 'إرسال ناجح ينتظر قرارًا.'], ['لا توجد نتائج', 'راجع الفلاتر والصفحة والصلاحية قبل اعتبارها مشكلة تقنية.']], 'تتعامل مع سبب المشكلة وتحافظ على البيانات.', [['ماذا أرسل لفريق الدعم؟', 'الرابط، الدور، اسم الإجراء، وقت المحاولة، نص الرسالة وصورة تخفي البيانات الخاصة. لا ترسل كلمة مرور أو رمز تحقق أو رابط ملف خاص.']], links(['التوثيق', '/admin/verification'], ['العمولات', '/admin/commissions/account'], ['البانرات', '/admin/banners'], ['التدقيق', '/admin/audit-logs'])),
    topic('daily-checklist', 'قائمة تشغيل يومية للأونر', 'ترتيب مهام الإدارة التي تحتاج متابعة.', 'حساب إدارة بالصلاحيات المناسبة لكل مهمة.', ['راجع التوثيق وطلبات المعلومات حتى لا تتعطل حسابات مقدمي الخدمة.', 'راجع العقارات والمشروعات المنتظرة وتأكد من جودة السعر والموقع والصور.', 'راجع الطلبات المتأخرة وتعيين المسؤول ومواعيد المعاينات.', 'راجع بلاغات المجتمع والحسابات والعقارات والطلبات، واتخذ قرارات موثقة.', 'راجع الإعلانات وإثباتات الدفع والبانرات المقبلة والمنتهية.', 'افتح الموقع بالعربية والإنجليزية، وراجع الرئيسية والمطورين والعقارات والمقالات، ثم راجع سجل التدقيق للتغييرات المهمة.'], [['قبل النشر', 'الصورة والمحتوى والرابط والموعد والحالة والصلاحية.'], ['قبل الحذف', 'اسم السجل وأثر الحذف والبديل المؤقت وسبب القرار.']], 'تتابع العمل حسب الأولوية وتراجع التغييرات بدل الاعتماد على الذاكرة.', [['كيف أشارك الشرح مع مسؤول؟', 'افتح الموضوع واضغط نسخ رابط الموضوع؛ يحتاج المستلم جلسة إدارة لقراءة الدليل.']], links(['نظرة عامة', '/admin'], ['التوثيق', '/admin/verification'], ['المتأخرة', '/admin/overdue-requests'], ['بلاغات المجتمع', '/admin/community/moderation'], ['البانرات', '/admin/banners']))
  ] }
];

export function normalizeGuideText(value: string): string {
  return value.toLocaleLowerCase().normalize('NFKD').replace(/[\u0300-\u036f\u064b-\u065f\u0670\u0640]/gu, '').replace(/[أإآٱ]/gu, 'ا').replace(/ى/gu, 'ي').replace(/ة/gu, 'ه');
}
export function searchGuide(query: string, sectionId = 'all', sections: readonly GuideSection[] = GUIDE_SECTIONS): GuideSection[] {
  const words = normalizeGuideText(query.trim()).split(/\s+/u).filter(Boolean);
  return sections.filter(section => sectionId === 'all' || section.id === sectionId).map(section => ({
    ...section,
    topics: section.topics.filter(item => {
      const haystack = normalizeGuideText([section.title, section.description, item.title, item.summary, item.before, ...item.steps, ...item.fields.flat(), item.result, ...item.questions.flat(), ...item.links.map(link => `${link.label} ${link.path}`), item.limitation ?? ''].join(' '));
      return words.every(word => haystack.includes(word));
    })
  })).filter(section => section.topics.length > 0);
}

export const GUIDE_SECTIONS: readonly GuideSection[] = BASE_GUIDE_SECTIONS.map(section => ({ ...section, topics: section.topics.map(updatedOwnerTopic) }));
